    "script": "Мы планировали выехать в пятницу вечером, но на работе назначили важную встречу, которую я не могу пропустить. Поэтому предлагаю отправиться в субботу утром. Билеты я уже проверила: места есть на поезд в восемь сорок. Ты, пожалуйста, уточни в гостинице, можно ли перенести заселение, а я пока узнаю условия обмена билетов. Если доплата окажется слишком большой, обсудим другой вариант.",
