    "script": "Я звоню по поводу квартиры, которую мы сняли на выходные. В объявлении было написано, что есть рабочий интернет и тихий двор. Интернет почти всё время пропадает, а под окнами с утра идёт ремонт. Мы приехали не только отдыхать, но и немного работать. Если устранить проблемы сегодня нельзя, предложите, пожалуйста, другую квартиру или возврат денег за оставшиеся ночи.",
