    "back": "Russian script (reference for future audio):\nЯ звоню по поводу квартиры, которую мы сняли на выходные. В объявлении было написано, что есть рабочий интернет и тихий двор. Интернет почти всё время пропадает, а под окнами с утра идёт ремонт. Мы приехали не только отдыхать, но и немного работать. Если устранить проблемы сегодня нельзя, предложите, пожалуйста, другую квартиру или возврат денег за оставшиеся ночи.\n\nAnswer key:\nAccommodation differs from the listing: unreliable internet and construction noise. Guests need to work. They request a fix today, otherwise another flat or refund for remaining nights.\n\nPractice: listen for the main idea first, replay for the requested detail, then check the script. Audio clips are not attached yet. Mark “Understood” only after an actual listening attempt; reading the script alone is not a listening review.",
