    "script": "Мне предложили две работы. В первой зарплата выше и офис рядом с домом, но задачи почти такие же, как сейчас. Во второй платят немного меньше и два раза в неделю нужно ездить далеко. Зато там можно освоить новое направление и работать с опытной командой. Я пока не решила: с одной стороны, хочется спокойствия, с другой — давно хочется профессионально вырасти.",
    "answer": "Job one: higher pay, close office, familiar tasks. Job two: lower pay, longer commute twice weekly, growth and experienced colleagues. The speaker is balancing stability against professional development.",
