    "front": "Explain the community project's problem, proposed fix, and measure of success.",
    "script": "В нашем дворе недавно поставили контейнер для обмена книгами. Сначала все обрадовались, но через месяц там оказалось много старых журналов и испорченных учебников. На собрании предложили написать понятные правила и раз в неделю проверять полки. Мы решили попробовать такой порядок до конца осени. Если люди снова начнут брать книги, значит, идея работает и контейнер стоит оставить.",
    "answer": "Unwanted or damaged materials accumulated. Add clear rules and weekly shelf checks until autumn ends. Success means people resume taking books; then the book-exchange box should stay.",
    "back": "Russian script (reference for future audio):\nВ нашем дворе недавно поставили контейнер для обмена книгами. Сначала все обрадовались, но через месяц там оказалось много старых журналов и испорченных учебников. На собрании предложили написать понятные правила и раз в неделю проверять полки. Мы решили попробовать такой порядок до конца осени. Если люди снова начнут брать книги, значит, идея работает и контейнер стоит оставить.\n\nAnswer key:\nUnwanted or damaged materials accumulated. Add clear rules and weekly shelf checks until autumn ends. Success means people resume taking books; then the book-exchange box should stay.\n\nPractice: listen for the main idea first, replay for the requested detail, then check the script. Audio clips are not attached yet. Mark “Understood” only after an actual listening attempt; reading the script alone is not a listening review.",
