    "script": "Вопрос: Вы сразу смогли выступать перед людьми? Ответ: Нет, первое выступление я почти полностью прочитал с листа и всё равно сильно нервничал. Потом стал готовить не полный текст, а короткий план, и репетировать перед двумя друзьями. Теперь говорить по теме легче. Но неожиданные вопросы пока даются трудно, поэтому после каждой встречи я записываю их и думаю, как можно было ответить.",
